let N = 100 ; let M = 100 ; let RR = 200 ; 

let X[] = new Array(N) ; let Y[] = new Array(N) ;
let R ; let A ; let I ; let II ; let Q ; 

function setup(){
  createCanvas(1112, 834) ; background(0) ;
	colorMode(HSB, 255);
  fill(0,0,0,10) ; stroke(255,0,0) ;
	window.simulatedMouseX = width/3;
	window.simulatedMouseY = height/2;
	strokeWeight(2);
  for ( I = 0 ; I < N ; I++ ){
    X[I] = random(-width/2,+width/2) ; Y[I] = random(-height/2,+height/2) ;
  }//I
}//setup()

function draw(){
	noStroke();
  rect(0,0,width,height) ;
	stroke(255);
	translate(250,150);
  for ( I = 0 ; I < N ; I++ ){
		for ( II = 0 ; II < M ; II++ ){
			R = sqrt(pow(X[I],2)+pow(Y[I],2)) ; 
      A = atan(Y[I]/X[I]) ;
      if ( X[I] < 0 ){ A = A+PI ; }  
			if ( X[I] >= 0 && Y[I] < 0 ){ A = A+(2*PI) ; }
      A = A/2 + Q ; R = R * sqrt(2) ;
      X[I] = R*cos(A) ; Y[I] = R*sin(A) ;
			Y[I] = Y[I]-RR ;
			stroke(I *2.5, 255, 255);
      point(X[I]+450,Y[I]+450) ; 
		}//II
		if( R > 30000 ){ X[I] = random(-width/2,+width/2) ; Y[I] = random(-width/2,+width/2) ; }
  }//let Q = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2)/width ;
	RR = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))+height/2 ;
}//draw()

